package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.ContactsContract;import android.provider.ContactsContract.CommonDataKinds.*;import java.util.*;
/** Optional fields on local raw contacts only. No account synchronization is configured. */
final class ContactExtras {
 static boolean local(Context c,long raw,long contact){try(Cursor r=c.getContentResolver().query(ContactsContract.RawContacts.CONTENT_URI,new String[]{"account_name","account_type"},"_id=? AND contact_id=? AND deleted=0",new String[]{""+raw,""+contact},null)){return r!=null&&r.moveToFirst()&&r.isNull(0)&&r.isNull(1);}}
 static String birthday(Context c,long raw){try(Cursor r=c.getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{Event.START_DATE},"raw_contact_id=? AND mimetype=? AND data2=?",new String[]{""+raw,Event.CONTENT_ITEM_TYPE,""+Event.TYPE_BIRTHDAY},null)){return r!=null&&r.moveToFirst()?r.getString(0):"";}}
 static int[] monthDay(String value){if(value==null||!value.matches("(?:[0-9]{4}|-)-[0-9]{2}-[0-9]{2}"))throw new IllegalArgumentException();String normalized=value.startsWith("--")?"2000"+value.substring(1):value;java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);f.setLenient(false);try{java.util.Calendar d=Calendar.getInstance();d.setTime(f.parse(normalized));return new int[]{d.get(Calendar.MONTH),d.get(Calendar.DAY_OF_MONTH)};}catch(Exception e){throw new IllegalArgumentException();}}
 static void birthday(Context c,long raw,long contact,String value)throws Exception{if(!local(c,raw,contact))throw new IllegalArgumentException();if(!value.isEmpty())monthDay(value);ArrayList<ContentProviderOperation> ops=new ArrayList<ContentProviderOperation>();ops.add(ContentProviderOperation.newDelete(ContactsContract.Data.CONTENT_URI).withSelection("raw_contact_id=? AND mimetype=? AND data2=?",new String[]{""+raw,Event.CONTENT_ITEM_TYPE,""+Event.TYPE_BIRTHDAY}).build());if(!value.isEmpty())ops.add(ContentProviderOperation.newInsert(ContactsContract.Data.CONTENT_URI).withValue("raw_contact_id",raw).withValue("mimetype",Event.CONTENT_ITEM_TYPE).withValue(Event.TYPE,Event.TYPE_BIRTHDAY).withValue(Event.START_DATE,value).build());c.getContentResolver().applyBatch(ContactsContract.AUTHORITY,ops);}
 static long group(Context c,String name){name=name.trim();if(name.isEmpty()||name.length()>64)throw new IllegalArgumentException();try(Cursor r=c.getContentResolver().query(ContactsContract.Groups.CONTENT_URI,new String[]{"_id"},"account_name IS NULL AND account_type IS NULL AND deleted=0 AND title=?",new String[]{"Leo · "+name},null)){if(r!=null&&r.moveToFirst())return r.getLong(0);}ContentValues v=new ContentValues();v.put(ContactsContract.Groups.TITLE,"Leo · "+name);v.put(ContactsContract.Groups.GROUP_VISIBLE,1);Uri u=c.getContentResolver().insert(ContactsContract.Groups.CONTENT_URI,v);if(u==null)throw new IllegalStateException();return ContentUris.parseId(u);}
 static boolean member(Context c,long raw,long group){try(Cursor r=c.getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{"_id"},"raw_contact_id=? AND mimetype=? AND data1=?",new String[]{""+raw,GroupMembership.CONTENT_ITEM_TYPE,""+group},null)){return r!=null&&r.moveToFirst();}}
 static void toggle(Context c,long raw,long contact,long group){if(!local(c,raw,contact))throw new IllegalArgumentException();try(Cursor g=c.getContentResolver().query(ContactsContract.Groups.CONTENT_URI,new String[]{"_id"},"_id=? AND account_name IS NULL AND account_type IS NULL AND deleted=0 AND title LIKE ?",new String[]{""+group,"Leo · %"},null)){if(g==null||!g.moveToFirst())throw new IllegalArgumentException();}String where="raw_contact_id=? AND mimetype=? AND data1=?";String[] args={""+raw,GroupMembership.CONTENT_ITEM_TYPE,""+group};if(member(c,raw,group))c.getContentResolver().delete(ContactsContract.Data.CONTENT_URI,where,args);else{ContentValues v=new ContentValues();v.put("raw_contact_id",raw);v.put("mimetype",GroupMembership.CONTENT_ITEM_TYPE);v.put(GroupMembership.GROUP_ROW_ID,group);if(c.getContentResolver().insert(ContactsContract.Data.CONTENT_URI,v)==null)throw new IllegalStateException();}}
}
